import{z as l,x as i,o as C,c as n,q as r,j as A,D as a,d as o,s as B,S as t,b as e}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"RoCE 与无损网络","description":"","frontmatter":{"title":"RoCE 与无损网络","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/roce-lossless.md","filePath":"cs/roce-lossless.md","lastUpdated":1791063341000}'),P={name:"cs/roce-lossless.md"};function d(p,E,D,c,F,R){const s=i("Mermaid");return C(),n("div",null,[E[2]||(E[2]=r('<h1 id="roce-与无损网络" tabindex="-1">RoCE 与无损网络 <a class="header-anchor" href="#roce-与无损网络" aria-label="Permalink to &quot;RoCE 与无损网络&quot;">​</a></h1><div class="epigraph"><p>RDMA 把远程内存操作放到网卡，绕过内核；RoCEv2 用 UDP/IP 承载，依赖 PFC 等把以太网做成「不丢」的假象。</p><footer>—— 据 InfiniBand 架构对照；RoCEv2 规范；IEEE 802.1Qbb 实践整理</footer></div><p><a href="/cs/pause-pfc">PFC</a> 与 <a href="/cs/dctcp">DCTCP</a> 已给反压与浅队列。<a href="/cs/dctcp">上一课</a> 仍是 TCP。缺口是 <strong>RoCE</strong>：网卡 QP、无损以太网、与 TCP 栈对照。本课结束转发面课序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>存储与 GPU 集合通信要微秒级、低 CPU。<a href="/cs/socket-api">套接字</a> 系统调用与拷贝太重。RDMA：RNIC 直接读写对端内存。InfiniBand 原生有基于信用的链路；RoCEv2 把 IB 运输装进 UDP，走 IP Clos——但 UDP 不重传，丢包让 QP 停顿昂贵，于是要 PFC 无损 + 可选 DCQCN。这是把端到端可靠性下放到链路与网卡，Saltzer 警告的那种优化：一旦无损失败，没有 TCP 兜底。</p><p>不要把 RoCE 写成「更快的 TCP」：语义是 RDMA，不是字节流。</p><p><span class="marginnote">RoCEv2 目的端口 4791。PFC 死锁与暂停风暴是已知运营风险。本课不写 verbs API 全集。</span></p><h3 id="rdma-怕丢" tabindex="-1">RDMA 怕丢 <a class="header-anchor" href="#rdma-怕丢" aria-label="Permalink to &quot;RDMA 怕丢&quot;">​</a></h3><p>RoCEv2 走 UDP/IP，靠 PFC/DCQCN 维持无损假象。失败恢复昂贵。语义不是字节流。留在数据中心。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：TCP 拷贝 vs RNIC 零拷贝。画：应用注册内存 → QP → RoCEv2 包 → PFC 队列。VXLAN 上跑 RoCE 要内层无损与外层 DSCP 映射，困难。</p><p><span class="marginnote">数字实例：MTU 从 1500 开到 9000 字节的巨帧，传同样 1 GB 的消息，包数从约 70 万降到约 12 万。包少了，包头开销、中断次数和收端软件处理都按比例缩水——这正是数据中心 RDMA 默认开巨帧的原因。</span></p>',12)),(C(),A(t,null,{default:a(()=>[B(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E6%B3%A8%E5%86%8C%E5%86%85%E5%AD%98%22%5D%20--%3E%20RNIC%5B%22RNIC%20QP%22%5D%0A%20%20RNIC%20--%3E%20UDP%5B%22RoCEv2%20over%20IP%22%5D%0A%20%20UDP%20--%3E%20PFC%5B%22%E4%BC%98%E5%85%88%E7%BA%A7%E6%9A%82%E5%81%9C%22%5D%0A%20%20DROP%5B%22%E4%BB%8D%E4%B8%A2%E5%88%99%20QP%20%E6%98%82%E8%B4%B5%E6%81%A2%E5%A4%8D%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[o(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"incast 对 RoCE 更致命，故 PFC+ECN。HOL：PFC 整类暂停会冻无关 QP。ECMP 乱序对 RDMA 不友好，常要保序或网卡重排。MTU 用巨帧摊头。与 5G URLLC 对照：都是用资源换尾延迟，一层在机房以太网，一层在空口。",-1)),E[5]||(E[5]=e("p",null,"多台发送方同时压向一个收端时，ECN 先降速、PFC 兜底防丢：",-1)),(C(),A(t,null,{default:a(()=>[B(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E5%A4%9A%E5%8F%91%E9%80%81%E6%96%B9%E5%90%8C%E6%97%B6%E5%8E%8B%E5%90%91%E4%B8%80%E5%8F%B0%E6%94%B6%E7%AB%AF%22%5D%20--%3E%20Q%5B%22%E6%94%B6%E7%AB%AF%E4%BA%A4%E6%8D%A2%E6%9C%BA%E9%98%9F%E5%88%97%E5%A0%86%E7%A7%AF%22%5D%0A%20%20Q%20--%3E%20T%7B%22%E6%B0%B4%E4%BD%8D%E8%B6%8A%E8%BF%87%20ECN%20%E9%98%88%E5%80%BC%EF%BC%9F%22%7D%0A%20%20T%20--%3E%7C%22%E6%9C%AA%E8%B6%8A%22%7C%20OK%5B%22%E6%AD%A3%E5%B8%B8%E8%BD%AC%E5%8F%91%22%5D%0A%20%20T%20--%3E%7C%22%E5%B7%B2%E8%B6%8A%22%7C%20ECN%5B%22%E4%BA%A4%E6%8D%A2%E6%9C%BA%E5%9C%A8%E5%8C%85%E4%B8%8A%E6%89%93%20ECN%20%E6%A0%87%E8%AE%B0%22%5D%0A%20%20ECN%20--%3E%20CN%5B%22%E6%94%B6%E7%AB%AF%E5%9B%9E%E4%BC%A0%E6%8B%A5%E5%A1%9E%E9%80%9A%E7%9F%A5%22%5D%0A%20%20CN%20--%3E%20RATE%5B%22%E5%8F%91%E9%80%81%E6%96%B9%E9%99%8D%E4%BD%8E%E5%8F%91%E9%80%81%E9%80%9F%E7%8E%87%22%5D%0A%20%20Q%20--%3E%7C%22%E7%BB%A7%E7%BB%AD%E9%80%BC%E8%BF%91%E7%BA%BF%E9%80%9F%E6%B0%B4%E4%BD%8D%22%7C%20PFC%5B%22PFC%20%E5%AF%B9%E8%AF%A5%E4%BC%98%E5%85%88%E7%BA%A7%E4%B8%8B%E5%8F%91%20PAUSE%22%5D%0A%20%20PFC%20--%3E%20HOLD%5B%22%E4%B8%8A%E6%B8%B8%E5%81%9C%E5%8F%91%E8%AF%A5%E7%B1%BB%E5%B8%A7%EF%BC%8C%E4%BF%9D%E8%AF%81%E4%B8%8D%E4%B8%A2%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[o(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p><span class="marginnote">术语翻译：ECN 就是「在包上贴一张『前面堵了』的便签、让发送方提前减速」的手段；PFC 则是「直接喊停一类帧」的硬反压。前者柔和但慢半拍，后者保丢零却会连累同优先级的无关流量。</span></p><p><span class="marginnote">常见误区：初学者容易以为「无损网络」就是整个网络不丢任何帧。实际 PFC 只对配置了的优先级类生效——被暂停的那一类会冻结整条队列，无关 QP 跟着遭殃（队头阻塞）；而没配 PFC 的流量照样丢。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 iWARP 的全部。AIMD 与 Chiu–Jain 是下一单元第一课。后课默认：RoCE 依赖无损与网卡卸载；失败模式与 TCP 不同。</p><p>互联网广域不假设 PFC，RoCE 留在数据中心。</p><p>下一课<a href="/cs/aimd-dynamics">AIMD 与 Chiu–Jain</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RoCEv2：RDMA over UDP/IP，怕丢。</li><li>PFC/DCQCN 维持无损假象，有暂停风险。</li><li>不替代公网 TCP。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RoCEv2；802.1Qbb；InfiniBand 对照。</li></ul>',8))])}const f=l(P,[["render",d]]);export{m as __pageData,f as default};
